function Assert($condition,[string]$message){if(-not$condition){throw $message}}
function Write-Text([string]$path,[string]$value){New-Item -ItemType Directory -Force -Path ([IO.Path]::GetDirectoryName($path))|Out-Null;[IO.File]::WriteAllText($path,$value,(New-Object Text.UTF8Encoding($false)))}
function New-LegacyRoot([string]$local,[string]$name){
  $root=Join-Path $local 'GRMetro\Performance Center';$files=@('package.json','apps/backend/src/index.js','GRMetro Performance Center.exe','scripts/windows/package-manifest.json','scripts/windows/package-build.json','scripts/windows/obsolete-tool.ps1')|Sort-Object
