  Write-Text (Join-Path $root 'scripts/windows/package-manifest.json') (([ordered]@{version=2;files=$files}|ConvertTo-Json -Depth 4)+[Environment]::NewLine);Write-Text (Join-Path $root 'scripts/windows/package-build.json') (([ordered]@{version=1;applicationVersion='1.0.0';commit='d159cba';sourceState='committed';nodeVersion='v24.18.1';builtAt='2026-09-25T21:10:36Z'}|ConvertTo-Json -Depth 4)+[Environment]::NewLine)
  $technicians=@(1..5|ForEach-Object{[ordered]@{id=400000+$_;name="Synthetic Tech $_";shortName="Tech $_";initials="T$_"}});$techJson=ConvertTo-Json -InputObject $technicians -Compress -Depth 5
  $environment="NODE_ENV=production`r`nHOST=127.0.0.1`r`nPORT=3000`r`nEDGE_DEBUG_URL=http://127.0.0.1:1`r`nEDGE_CONNECTION_TIMEOUT_MILLISECONDS=1000`r`nSERVICETITAN_BASE_URL=https://go.servicetitan.com`r`nSERVICETITAN_REQUEST_TIMEOUT_MILLISECONDS=2000`r`nSERVICETITAN_CSRF_TIMEOUT_MILLISECONDS=1000`r`nSERVICETITAN_RELOAD_KEY=2`r`nSERVICETITAN_DRILLDOWN_KPI_TYPE=2`r`nSERVICETITAN_BUSINESS_UNIT_IDS=1001`r`nSERVICETITAN_TECHNICIANS_JSON=$techJson`r`nTIMEZONE=America/New_York`r`nREFRESH_INTERVAL_SECONDS=60`r`nREMOTE_OVERRIDE_SECONDS=120`r`nRETURN_TRANSITION_MILLISECONDS=1000`r`nSTALE_WARNING_SECONDS=180`r`nSTALE_CRITICAL_SECONDS=600`r`nSNAPSHOT_RETENTION_LIMIT=10`r`nTREND_MINIMUM_HISTORY=4`r`nDASHBOARD_BASE_URL=http://127.0.0.1:3000`r`nMOCK_MODE=false`r`nENABLE_DEVELOPMENT_ROUTES=false`r`nLOG_LEVEL=error`r`nJSON_BODY_LIMIT=100kb`r`nREMOTE_RATE_LIMIT_WINDOW_SECONDS=60`r`nREMOTE_RATE_LIMIT_MAX_REQUESTS=30`r`n"
  Write-Text (Join-Path $root '.env') $environment;foreach($relative in @('data/company-config.json','data/goals.json','data/display-settings.json','data/management-dismissals.json','apps/backend/data/spreadsheet-slide.json')){Write-Text (Join-Path $root $relative) '{}'};Write-Text (Join-Path $root 'logs/supervisor.log') 'SYNTHETIC LOG';Write-Text (Join-Path $root '.grmetro-autostart-choice') 'no';return $root
}
function Get-FreePort{$listener=New-Object Net.Sockets.TcpListener([Net.IPAddress]::Loopback,0);$listener.Start();$port=([Net.IPEndPoint]$listener.LocalEndpoint).Port;$listener.Stop();return $port}
$savedLocal=$env:LOCALAPPDATA;$savedApp=$env:APPDATA;$savedTest=$env:GRMETRO_UPDATER_TEST_MODE
try{
  New-Item -ItemType Directory -Path $fixture|Out-Null;$candidate=Join-Path $fixture 'GRMetro-Legacy-Upgrade-2026.10.26.3-INTERNAL-READY.cmd'
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $repository 'scripts/windows/build-legacy-single-file-upgrade.ps1') -ApplicationPackage (Join-Path $repository 'dist/windows-packages/GRMetro-2026.10.26.3/grmetro-performance-center-package.zip') -UpdateHostMigrationBundle (Join-Path $repository 'dist/windows-update-host-migrations/GRMetro-Update-Host-2026.10.26.2/grmetro-update-host-migration-2026.10.26.2.zip') -ReleaseVersion '2026.10.26.3' -LegacyCommit d159cba -OutputPath $candidate|Out-Null;if($LASTEXITCODE-ne0){throw 'Single-file candidate build failed.'}
  $incompatibleLocal=Join-Path $fixture 'incompatible-local';$incompatibleRoot=Join-Path $incompatibleLocal 'GRMetro\Performance Center';Write-Text (Join-Path $incompatibleRoot 'scripts\windows\package-build.json') '{"schemaVersion":2,"releaseVersion":"2026.10.21.2","commit":"modern"}';Write-Text (Join-Path $incompatibleRoot 'scripts\windows\package-manifest.json') '{"version":2,"files":[]}'
  $env:LOCALAPPDATA=$incompatibleLocal;$incompatibleOutput=& cmd.exe /d /c ('"{0}" < NUL'-f$candidate) 2>&1;$incompatibleExit=$LASTEXITCODE;$env:LOCALAPPDATA=$savedLocal;Assert ($incompatibleExit-eq1-and($incompatibleOutput|Out-String)-match'Unsupported production baseline') 'Single-file bootstrap did not reject an incompatible installation before mutation.';Assert (-not(Test-Path (Join-Path $incompatibleLocal 'GRMetro\Update Host'))) 'Incompatible rejection installed an Update Host.'
  $self=[IO.File]::ReadAllText($candidate);$marker='::GRMETRO_PAYLOAD_BEGIN::';$index=$self.IndexOf($marker,[StringComparison]::Ordinal);Assert ($index-gt0) 'Candidate payload marker missing.';$payloadZip=Join-Path $fixture 'payload.zip';[IO.File]::WriteAllBytes($payloadZip,[Convert]::FromBase64String(($self.Substring($index+$marker.Length)-replace'\s','')));$payloadRoot=Join-Path $fixture 'payload';Add-Type -AssemblyName System.IO.Compression.FileSystem;[IO.Compression.ZipFile]::ExtractToDirectory($payloadZip,$payloadRoot);$reviewRoot=Join-Path $fixture 'review';[IO.Compression.ZipFile]::ExtractToDirectory((Join-Path $payloadRoot 'review.zip'),$reviewRoot)
  foreach($line in Get-Content (Join-Path $reviewRoot 'SHA256SUMS.txt')){$null=$line-match'^([A-F0-9]{64})  (.+)$';Assert $matches[1] 'Malformed review checksum.';Assert ((Get-FileHash (Join-Path $reviewRoot $matches[2])-Algorithm SHA256).Hash-eq$matches[1]) "Review checksum mismatch: $($matches[2])"}
  $scripts=Join-Path $reviewRoot 'scripts\windows';. (Join-Path $scripts 'legacy-composite-upgrade.ps1');$app=Join-Path $reviewRoot 'payload\dashboard.zip';$hostBundle=Join-Path $reviewRoot 'payload\update-host-migration.zip';$appHash=(Get-FileHash $app -Algorithm SHA256).Hash;$hostHash=(Get-FileHash $hostBundle -Algorithm SHA256).Hash;$hostPreflight={param($application,$version,$bundle,$hash)[pscustomobject]@{Status='validated';AuthenticodeStatus='NotSigned';UpdateDiscoveryStatus='up-to-date'}};$privatePreflight={param($package,$install)[pscustomobject]@{Compatible=$true;TechnicianCount=5;EnvironmentUnchanged=$true;ServiceTitanContacted=$false}}
  $successLocal=Join-Path $fixture 'success-local';$env:LOCALAPPDATA=$successLocal;$env:APPDATA=Join-Path $fixture 'success-appdata';$env:GRMETRO_UPDATER_TEST_MODE='true';$successRoot=New-LegacyRoot $successLocal 'success';$privateHash=(Get-FileHash (Join-Path $successRoot '.env')-Algorithm SHA256).Hash;$script:started=$false
  $success=Invoke-GrMetroLegacyCompositeUpgrade -Root $successRoot -Zip $app -ExpectedHash $appHash -Version '2026.10.26.3' -LegacyCommit d159cba -HostBundle $hostBundle -HostHash $hostHash -ConfirmDefender -ConfirmRollback -ConfirmUnsigned -AllowTestRoot -Port (Get-FreePort) -PrivateConfigurationAction $privatePreflight -HostValidationAction $hostPreflight -SaveLaunchAction {param($root)[pscustomobject]@{Saved=$true}} -SetLaunchAction {param($root,$enabled)Assert (-not$enabled) 'Autostart changed.';[pscustomobject]@{HostExecutable=(Join-Path $env:LOCALAPPDATA 'GRMetro\Update Host\GRMetro Update Host.exe')}} -StartApplicationAction {$script:started=$true}
  Assert ($success.Status-eq'complete'-and$script:started) 'Composite candidate upgrade did not complete.';$identity=Get-Content (Join-Path $successRoot 'scripts/windows/package-build.json')-Raw|ConvertFrom-Json;Assert ($identity.releaseVersion-eq'2026.10.26.3'-and$identity.commit-eq'731d5ad8047b711472bc44714b414f4281af8676') 'Target identity mismatch.';Assert ((Get-FileHash (Join-Path $successRoot '.env')-Algorithm SHA256).Hash-eq$privateHash) 'Successful upgrade changed .env.';Assert (Test-Path (Join-Path $successLocal 'GRMetro\Update Host\GRMetro Update Host.exe')) 'Successful upgrade omitted Update Host.';Assert (-not(Test-Path ($successRoot+'.upgrade-transaction'))) 'Successful upgrade left a transaction.'
