  try{Invoke-GrMetroLegacyCompositeUpgrade -Root $failureRoot -Zip $app -ExpectedHash $appHash -Version '2026.10.26.3' -LegacyCommit d159cba -HostBundle $hostBundle -HostHash $hostHash -ConfirmDefender -ConfirmRollback -ConfirmUnsigned -AllowTestRoot -PrivateConfigurationAction $privatePreflight -HostValidationAction $hostPreflight -ManualUpgradeAction {param($application,$port) Invoke-GrMetroManualLegacyUpgrade -Root $application.InstallRoot -Zip $application.PackageZip -ExpectedHash $application.PackageSha256 -ExpectedVersion '2026.10.26.3' -ExpectedCommit d159cba -ConfirmDefenderReview -ConfirmRollbackSource -DeferCommitCleanup -AllowTestRoot -PrivateConfigurationAction {param($package,$install)[pscustomobject]@{Compatible=$true;TechnicianCount=5;EnvironmentUnchanged=$true;ServiceTitanContacted=$false}} -StopProcessesAction {} -ValidationAction {throw 'INJECTED FINAL VALIDATION FAILURE'}} -SaveLaunchAction {param($root)[pscustomobject]@{Saved=$true}} -SetLaunchAction {param($root,$enabled)[pscustomobject]@{HostExecutable='unused'}} -StartApplicationAction {}|Out-Null}catch{$failed=$_.Exception.Message}
  Assert ($failed-match'previous application was restored|prior application and Update Host state were restored') 'Injected failure did not report rollback.';Assert ((Get-FileHash (Join-Path $failureRoot 'apps/backend/src/index.js')-Algorithm SHA256).Hash-eq$oldHash) 'Rollback did not restore legacy application.';Assert ((Get-FileHash (Join-Path $failureRoot '.env')-Algorithm SHA256).Hash-eq$privateHash) 'Rollback changed .env.';Assert (-not(Test-Path (Join-Path $failureLocal 'GRMetro\Update Host'))) 'Rollback left a new Update Host.';Assert (-not(Test-Path ($failureRoot+'.upgrade-transaction'))) 'Rollback left a transaction.'
